from cardio_1 import a, G
from cardio_2 import t
# J84 — Pneumopathies interstitielles diffuses et éosinophilies pulmonaires (P-02-Pneumologie)
a('PID',[('P','Pneumopathie'),('I','Interstitielle'),('D','Diffuse')],'Pneumopathie interstitielle diffuse','<p>Groupe de plus de deux cents maladies qui atteignent d’abord l’interstitium pulmonaire, c’est-à-dire la paroi alvéolaire, les septums interlobulaires et le tissu conjonctif péribronchovasculaire. Équivalent anglais : ILD (interstitial lung disease).</p>','j84-pid')
a('FPI',[('F','Fibrose'),('P','Pulmonaire'),('I','Idiopathique')],'Fibrose pulmonaire idiopathique','<p>Pneumopathie interstitielle fibrosante chronique, progressive, sans cause identifiée, limitée au poumon, qui associe un aspect de pneumopathie interstitielle commune en imagerie ou en histologie. Codée J84.1 en CIM-10-GM 2024.</p>','j84-fpi')
a('FPP',[('F','Fibrose'),('P','Pulmonaire'),('P','Progressive')],'Fibrose pulmonaire progressive','<p>Définition ATS/ERS/JRS/ALAT 2022 : chez un patient atteint d’une pneumopathie interstitielle fibrosante autre que la fibrose pulmonaire idiopathique, au moins deux des trois critères (symptômes, fonction, imagerie) d’aggravation sur un an sans autre explication.</p>','j84-fpp')
a('PINS',[('P','Pneumopathie'),('I','Interstitielle'),('N','Non'),('S','Spécifique')],'Pneumopathie interstitielle non spécifique','<p>Forme histologique et radiologique de pneumopathie interstitielle à atteinte homogène dans le temps, souvent associée à une connectivite. Équivalent anglais : NSIP.</p>','j84-pins')
a('NSIP',[('N','Nonspecific'),('S','(non spécifique)'),('I','Interstitial'),('P','Pneumonia')],'Nonspecific interstitial pneumonia (pneumopathie interstitielle non spécifique)','<p>Terme anglais de la PINS, employé dans les recommandations internationales.</p>','j84-pins')
a('PIC',[('P','Pneumopathie'),('I','Interstitielle'),('C','Commune')],'Pneumopathie interstitielle commune','<p>Aspect radiologique et histologique (fibrose sous-pleurale et basale, rayon de miel, hétérogénéité temporelle) qui caractérise la fibrose pulmonaire idiopathique lorsqu’aucune cause n’est trouvée. Équivalent anglais : UIP.</p>','j84-pic')
a('UIP',[('U','Usual'),('I','Interstitial'),('P','Pneumonia')],'Usual interstitial pneumonia (pneumopathie interstitielle commune)','<p>Terme anglais de la PIC ; « usual » signifie « habituelle », d’où la traduction française « commune ».</p>','j84-pic')
a('LBA',[('L','Lavage'),('B','Broncho'),('A','Alvéolaire')],'Lavage bronchoalvéolaire','<p>Instillation puis aspiration de sérum physiologique dans un segment pulmonaire au cours d’une bronchoscopie ; l’analyse cellulaire et microbiologique du liquide renseigne sur l’espace alvéolaire.</p>','j84-lba')
a('KCO',[('K','Coefficient de transfert (constante K)'),('CO','du monoxyde de Carbone (CO)')],'Coefficient de transfert du monoxyde de carbone','<p>Rapport DLCO / volume alvéolaire. Il exprime la diffusion par unité de volume pulmonaire ventilé et aide à distinguer une perte de surface d’échange d’une atteinte de la membrane.</p>','j84-dlco')
a('GM-CSF',[('GM','Granulocyte-Macrophage'),('C','Colony-'),('S','Stimulating'),('F','Factor')],'Facteur de croissance des colonies de granulocytes et de macrophages','<p>Cytokine indispensable à la maturation du macrophage alvéolaire et au catabolisme du surfactant. Des autoanticorps anti-GM-CSF causent la protéinose alvéolaire auto-immune.</p>','j84-pap')
a('JRS',[('J','Japanese'),('R','Respiratory'),('S','Society')],'Japanese Respiratory Society (Société japonaise de pneumologie)','<p>Coautrice des recommandations internationales sur la fibrose pulmonaire idiopathique (2011, 2015, 2018, 2022).</p>')
a('ALAT',[('A','Asociación'),('LA','Latinoamericana de'),('T','Tórax')],'Asociación Latinoamericana de Tórax (Association latino-américaine de pneumologie)','<p>Coautrice des recommandations internationales sur la fibrose pulmonaire idiopathique. Dans ce cours, le sigle ne désigne jamais l’alanine aminotransférase, écrite en toutes lettres.</p>')
a('GAP',[('G','Gender (sexe)'),('A','Age (âge)'),('P','Physiology (physiologie : CVF et DLCO)')],'Indice pronostique GAP (sexe, âge, physiologie)','<p>Score de Ley et al. (2012) qui classe la fibrose pulmonaire idiopathique en trois stades de mortalité à un an à partir du sexe, de l’âge, de la CVF et de la DLCO.</p>','j84-gap')
a('ISHLT',[('I','International'),('S','Society for'),('H','Heart and'),('L','Lung'),('T','Transplantation')],'International Society for Heart and Lung Transplantation (Société internationale de transplantation cardiaque et pulmonaire)','<p>Publie le consensus sur l’adressage et l’inscription des candidats à la transplantation pulmonaire (version 2021).</p>','j84-tx')
a('MUC5B',[('MUC','MUCine'),('5B','5B (isoforme)')],'Gène de la mucine 5B','<p>Gène d’une mucine des voies aériennes distales. Le variant de son promoteur rs35705950 est le principal facteur de risque génétique commun de la fibrose pulmonaire idiopathique.</p>','j84-gen')
a('TERT',[('T','TElomerase'),('R','Reverse'),('T','Transcriptase')],'Transcriptase inverse de la télomérase','<p>Sous-unité catalytique de la télomérase ; ses variants pathogènes raccourcissent les télomères et causent des fibroses pulmonaires familiales.</p>','j84-gen')
a('TERC',[('TE','TElomerase'),('R','RNA'),('C','Component')],'Composant ARN de la télomérase','<p>Matrice d’ARN de la télomérase ; ses variants pathogènes provoquent, comme ceux de TERT, une maladie des télomères courts.</p>','j84-gen')
a('SFTPC',[('SFTP','SurFacTant Protein'),('C','C')],'Gène de la protéine C du surfactant','<p>Gène exprimé par les pneumocytes de type II ; ses variants entraînent un mauvais repliement protéique et des pneumopathies interstitielles de l’enfant ou de l’adulte.</p>','j84-gen')
a('SFTPA2',[('SFTP','SurFacTant Protein'),('A2','A2')],'Gène de la protéine A2 du surfactant','<p>Variants associés à des fibroses pulmonaires familiales et à des adénocarcinomes pulmonaires.</p>','j84-gen')
a('SFTPB',[('SFTP','SurFacTant Protein'),('B','B')],'Gène de la protéine B du surfactant','<p>Un déficit complet provoque une détresse respiratoire néonatale et une protéinose alvéolaire congénitale.</p>','j84-gen')
a('ABCA3',[('ABC','ATP-Binding Cassette (transporteur à cassette liant l’ATP)'),('A3','sous-famille A, membre 3')],'Transporteur ABCA3','<p>Transporteur lipidique des corps lamellaires des pneumocytes de type II ; ses variants biallèliques causent des pneumopathies interstitielles de l’enfant.</p>','j84-gen')
a('SLC34A2',[('SLC','SoLute Carrier (transporteur de soluté)'),('34','famille 34'),('A2','membre A2')],'Cotransporteur sodium-phosphate de type IIb','<p>Transporteur qui retire le phosphate de l’espace alvéolaire. Ses variants biallèliques causent la microlithiase alvéolaire pulmonaire.</p>','j84-gen')
a('CSF2RA',[('CSF2','Colony-Stimulating Factor 2 (GM-CSF)'),('R','Receptor'),('A','Alpha')],'Chaîne alpha du récepteur du GM-CSF','<p>Ses variants biallèliques (ou ceux de CSF2RB) causent la protéinose alvéolaire héréditaire, sans autoanticorps.</p>','j84-gen')
a('CSF2RB',[('CSF2','Colony-Stimulating Factor 2 (GM-CSF)'),('R','Receptor'),('B','Bêta')],'Chaîne bêta du récepteur du GM-CSF','<p>Ses variants biallèliques causent, comme ceux de CSF2RA, une protéinose alvéolaire héréditaire.</p>','j84-gen')
a('PDGFR',[('PDGF','Platelet-Derived Growth Factor'),('R','Receptor')],'Récepteur du facteur de croissance dérivé des plaquettes','<p>Récepteur à activité tyrosine kinase des fibroblastes, cible du nintédanib.</p>','j84-d-nint')
a('FGFR',[('FGF','Fibroblast Growth Factor'),('R','Receptor')],'Récepteur du facteur de croissance des fibroblastes','<p>Récepteur à activité tyrosine kinase, cible du nintédanib.</p>','j84-d-nint')
a('FGF',[('F','Fibroblast'),('G','Growth'),('F','Factor')],'Facteur de croissance des fibroblastes','<p>Famille de facteurs de croissance qui stimulent la prolifération des fibroblastes et l’angiogenèse.</p>')
a('VEGFR',[('VEGF','Vascular Endothelial Growth Factor'),('R','Receptor')],'Récepteur du facteur de croissance de l’endothélium vasculaire','<p>Récepteur à activité tyrosine kinase ; son inhibition par le nintédanib explique le risque hémorragique et la protéinurie rapportés.</p>','j84-d-nint')
a('PDE4B',[('PDE','PhosphoDiEstérase'),('4B','de type 4, isoforme B')],'Phosphodiestérase de type 4B','<p>Enzyme qui dégrade l’AMPc dans les cellules inflammatoires et les fibroblastes ; cible préférentielle du nérandomilast.</p>','j84-d-neran')
a('CCP',[('C','Cyclic (cyclique)'),('C','Citrullinated (citrulliné)'),('P','Peptide')],'Peptide cyclique citrulliné','<p>Les anticorps anti-peptide cyclique citrulliné sont spécifiques de la polyarthrite rhumatoïde, cause fréquente de pneumopathie interstitielle.</p>')
a('MDA5',[('MDA','Melanoma Differentiation-Associated protein'),('5','5')],'Protéine 5 associée à la différenciation du mélanome','<p>Cible d’autoanticorps de la dermatomyosite amyopathique, associée à une pneumopathie interstitielle rapidement progressive.</p>')
a('CCL11',[('CC','chimiokine à motif CC'),('L','Ligand'),('11','11')],'Ligand 11 des chimiokines CC (éotaxine 1)','<p>Chimiokine qui attire les éosinophiles vers le poumon par le récepteur CCR3.</p>','j84-eosbio')
a('CCR3',[('CC','chimiokine à motif CC'),('R','Récepteur'),('3','3')],'Récepteur 3 des chimiokines CC','<p>Récepteur des éotaxines exprimé par les éosinophiles.</p>','j84-eosbio')
a('CYP2E1',[('CYP','CYtochrome P450'),('2E1','famille 2, sous-famille E, isoforme 1')],'Cytochrome P450 2E1','<p>Isoenzyme qui participe accessoirement au métabolisme de la pirfénidone.</p>')
a('J84.0',[('J84.0','Code CIM-10-GM J84.0')],'Pneumopathies alvéolaires et pariéto-alvéolaires','<p>Protéinose alvéolaire et microlithiase alvéolaire pulmonaire. Cinquième caractère : 0 sans exacerbation aiguë, 1 avec exacerbation aiguë.</p>')
a('J84.1',[('J84.1','Code CIM-10-GM J84.1')],'Autres affections pulmonaires interstitielles avec fibrose','<p>Fibrose pulmonaire idiopathique, pneumopathie interstitielle commune, pneumopathie interstitielle aiguë (syndrome de Hamman-Rich), alvéolite fibrosante cryptogénique.</p>')
a('J84.8',[('J84.8','Code CIM-10-GM J84.8')],'Autres affections pulmonaires interstitielles précisées','<p>Pneumopathie interstitielle de nature précisée qui n’a pas de rubrique propre.</p>')
a('J84.9',[('J84.9','Code CIM-10-GM J84.9')],'Affection pulmonaire interstitielle, sans précision','<p>Pneumopathie interstitielle sans autre précision.</p>')
a('J84.10',[('J84.10','Code CIM-10-GM J84.1, cinquième caractère 0')],'Affection interstitielle avec fibrose, sans exacerbation aiguë','<p>Exemple : fibrose pulmonaire idiopathique stable.</p>')
a('J84.11',[('J84.11','Code CIM-10-GM J84.1, cinquième caractère 1')],'Affection interstitielle avec fibrose, avec exacerbation aiguë','<p>Exemple : exacerbation aiguë d’une fibrose pulmonaire idiopathique.</p>')
a('J70.1',[('J70.1','Code CIM-10-GM J70.1')],'Affections pulmonaires chroniques et autres dues à des radiations','<p>Fibrose pulmonaire après irradiation ; exclue de J84.</p>')
a('J70.2',[('J70.2','Code CIM-10-GM J70.2')],'Affections pulmonaires interstitielles aiguës dues à des médicaments','<p>Exclues de J82 et de J84.</p>')
a('J70.3',[('J70.3','Code CIM-10-GM J70.3')],'Affections pulmonaires interstitielles chroniques dues à des médicaments','<p>Exclues de J82 et de J84.</p>')
a('J70.4',[('J70.4','Code CIM-10-GM J70.4')],'Affections pulmonaires interstitielles dues à des médicaments, sans précision','<p>Exclues de J82 et de J84.</p>')
a('J68.4',[('J68.4','Code CIM-10-GM J68.4')],'Affections respiratoires chroniques dues à des agents chimiques, émanations, fumées et gaz','<p>Comprend la fibrose pulmonaire chronique d’inhalation ; exclue de J84.1.</p>')
a('J98.2',[('J98.2','Code CIM-10-GM J98.2')],'Emphysème interstitiel','<p>Air dans l’interstitium pulmonaire ; exclu de J84.</p>')
a('D72.1',[('D72.1','Code CIM-10-GM D72.1')],'Éosinophilie','<p>Code de l’éosinophilie sanguine et des syndromes hyperéosinophiliques lorsqu’ils ne relèvent pas d’une autre rubrique.</p>')
t('INPULSIS',[('INPULSIS','nom d’essai de Boehringer Ingelheim, non développable lettre à lettre')],'Essais INPULSIS-1 et INPULSIS-2 (2014)','<p>Nintédanib 150 mg deux fois par jour contre placebo dans la fibrose pulmonaire idiopathique : déclin annuel de la CVF réduit d’environ moitié (données regroupées −113,6 contre −223,5 mL par an).</p>','j84-d-nint')
t('INBUILD',[('INBUILD','nom d’essai de Boehringer Ingelheim, non développable lettre à lettre')],'Essai INBUILD (2019)','<p>Nintédanib contre placebo dans les pneumopathies interstitielles fibrosantes progressives autres que la fibrose pulmonaire idiopathique : déclin annuel de la CVF −80,8 contre −187,8 mL.</p>','j84-d-nint')
t('SENSCIS',[('SENSCIS','Safety and Efficacy of Nintedanib in Systemic SClerosIS (non strictement lettre à lettre)')],'Essai SENSCIS (2019)','<p>Nintédanib contre placebo dans la pneumopathie interstitielle de la sclérodermie systémique : ralentissement du déclin de la CVF.</p>','j84-d-nint')
t('ASCEND',[('ASCEND','Assessment of pirfenidone to Confirm Efficacy aND safety (non strictement lettre à lettre)')],'Essai ASCEND (2014)','<p>Pirfénidone contre placebo dans la fibrose pulmonaire idiopathique : proportion de patients avec déclin de la CVF ≥ 10 % ou décès à 52 semaines réduite de 31,8 % à 16,5 %.</p>','j84-d-pirf')
t('CAPACITY',[('CAPACITY','Clinical Studies Assessing Pirfenidone in idiopathic pulmonary fibrosis: reseArch of effiCacy and safety outcomes (non strictement lettre à lettre)')],'Essais CAPACITY (PIPF-004 et PIPF-006, 2011)','<p>Deux essais de la pirfénidone contre placebo sur 72 semaines ; le premier a atteint son critère principal, le second non.</p>','j84-d-pirf')
t('PANTHER-IPF',[('PANTHER','Prednisone, Azathioprine, and N-acetylcysteine: a sTudy that evaluates Response in IPF (non strictement lettre à lettre)'),('IPF','Idiopathic Pulmonary Fibrosis')],'Essai PANTHER-IPF (2012)','<p>L’association prednisone, azathioprine et N-acétylcystéine a augmenté la mortalité et les hospitalisations dans la fibrose pulmonaire idiopathique ; son bras a été arrêté prématurément.</p>','j84-d-cs')
t('FIBRONEER-IPF',[('FIBRONEER','nom d’essai de Boehringer Ingelheim, non développable lettre à lettre'),('IPF','Idiopathic Pulmonary Fibrosis')],'Essai FIBRONEER-IPF (2025)','<p>Nérandomilast 9 ou 18 mg deux fois par jour contre placebo dans la fibrose pulmonaire idiopathique : variation de la CVF à 52 semaines −114,7 mL (18 mg), −138,6 mL (9 mg), −183,5 mL (placebo).</p>','j84-d-neran')
t('FIBRONEER-ILD',[('FIBRONEER','nom d’essai de Boehringer Ingelheim, non développable lettre à lettre'),('ILD','Interstitial Lung Disease')],'Essai FIBRONEER-ILD (2025)','<p>Nérandomilast contre placebo dans la fibrose pulmonaire progressive : critère principal (variation de la CVF à 52 semaines) atteint.</p>','j84-d-neran')
t('EXAFIP',[('EXA','EXAcerbation'),('FIP','de Fibrose Idiopathique Pulmonaire')],'Essai EXAFIP (2022)','<p>Ajout de cyclophosphamide intraveineux aux corticostéroïdes dans l’exacerbation aiguë de fibrose pulmonaire idiopathique : mortalité à trois mois plus élevée que sous placebo.</p>','j84-ea')
t('SLS II',[('S','Scleroderma'),('L','Lung'),('S','Study'),('II','deuxième essai')],'Essai Scleroderma Lung Study II (2016)','<p>Mycophénolate mofétil 3 g par jour pendant 24 mois contre cyclophosphamide oral 12 mois dans la pneumopathie de la sclérodermie : efficacité comparable sur la CVF, meilleure tolérance du mycophénolate.</p>','j84-d-mmf')
t('IMPALA-2',[('IMPALA','IMproving Pulmonary function by inhaled molgrAmostim in autoimmune puLmonary Alveolar proteinosis (non strictement lettre à lettre)'),('2','deuxième essai')],'Essai IMPALA-2 (2025)','<p>Molgramostim inhalé 300 µg par jour contre placebo dans la protéinose alvéolaire auto-immune : amélioration de la DLCO à 24 semaines.</p>','j84-d-gmcsf')
a('EFR',[('E','Épreuves'),('F','Fonctionnelles'),('R','Respiratoires')],'Épreuves fonctionnelles respiratoires','<p>Ensemble de la spirométrie, de la mesure des volumes pulmonaires (pléthysmographie) et de la DLCO. Dans une pneumopathie interstitielle, elles montrent une restriction et une baisse de la DLCO.</p>','j84-efr')
a('EMCS',[('E','Exposition'),('M','Médicament'),('C','Connectivite'),('S','Sarcoïdose')],'Aide-mémoire EMCS (aide pédagogique, non critère officiel)','<p>Ordre de recherche des causes d’une pneumopathie interstitielle : exposition, médicament, connectivite, sarcoïdose.</p>','j84-mnemo')
a('FDA',[('F','Food and'),('D','Drug'),('A','Administration')],'Food and Drug Administration (agence américaine des produits alimentaires et des médicaments)','<p>Autorité fédérale américaine qui autorise la mise sur le marché des médicaments aux États-Unis ; son autorisation ne vaut pas autorisation en Suisse.</p>')
a('GATA2',[('GATA2','gène du facteur de transcription qui se lie à la séquence d’ADN « GATA », membre 2')],'Gène GATA2','<p>Facteur de transcription des cellules souches hématopoïétiques. Son déficit réduit les monocytes, les cellules dendritiques et les lymphocytes B et NK ; il peut causer une protéinose alvéolaire secondaire et des infections mycobactériennes.</p>','j84-gen')
a('Hamman-Rich',[('Hamman-Rich','nom propre : Louis Hamman et Arnold Rich, médecins américains qui ont décrit la maladie en 1935 et 1944 ; ce n’est pas une abréviation')],'Syndrome de Hamman-Rich','<p>Ancien nom de la pneumopathie interstitielle aiguë idiopathique, codée J84.1 en CIM-10-GM 2024.</p>','j84-pia')
a('McCarthy',[('McCarthy','nom propre : Cormac McCarthy, pneumologue, premier auteur de l’étude de prévalence de la protéinose alvéolaire (2018) ; ce n’est pas une abréviation')],'McCarthy C. et al. (2018)','<p>Étude de prévalence de la protéinose alvéolaire auto-immune aux États-Unis et au Japon, publiée dans l’American Journal of Respiratory and Critical Care Medicine.</p>','j84-pap')
t('AmbOx',[('Amb','Ambulatory'),('Ox','Oxygen')],'Essai AmbOx (2018)','<p>Essai croisé randomisé : l’oxygène ambulatoire a amélioré la qualité de vie liée à la maladie chez des patients atteints de pneumopathie interstitielle qui désaturaient à l’effort sans hypoxémie de repos.</p>','j84-o2')
